//! The plan's SURFACES section (`epic-the-lexicographer-defines-the-applications-language`) — the
//! roster's counterpart to `features`, and the step between discovery and distribution of work.
//!
//! # Why the plan holds this at all
//!
//! `bsc surface` already answers what EXISTS: 68 nouns, 460 verbs, 57 crates serving them, live and
//! derived. That is what the lexicographer READS. It is not something anyone can be assigned — a
//! catalog row cannot carry a decision, a status, or an owner, so nothing can be handed down from it.
//!
//! Features solved this shape already. The director runs discovery, records `bsc plan feature`, and
//! work is distributed from the plan; the surfaces section is the same move one tier over:
//!
//! ```text
//! director       discovery -> the FEATURES section -> feature work to workers
//! lexicographer  discovery -> the SURFACES section -> surface work to noun/verb sessions
//! ```
//!
//! # A row is a DECISION, never a copy of the catalog
//!
//! Nothing here restates what `bsc surface` can derive — not the verb list, not the summary, not the
//! store a noun touches. A row that did would be a fourth roster to drift, and this repository has
//! already paid for three (the studio session set, the packaged-config globs, and the Glance drill's
//! packaged team file). What the row holds is the part no catalog can compute: what should CHANGE
//! about this crate, why, and who is doing it.
//!
//! # Keyed on the CRATE
//!
//! Settled with the maintainer: the unit is the whole crate, not the noun and not the verb. Crate to
//! noun was never 1:1 — `bsc` serves 6 nouns, `logs` 3, and four crates serve 2 — so a roster
//! decision routinely spans nouns inside one crate, and folding one noun into another spans two. A
//! row keyed on the noun could not express either.

use crate::Store;
use rusqlite::params;
use serde::{Deserialize, Serialize};

/// The decisions a roster row can carry. Deliberately closed: a free-text decision is a note, and
/// notes are what this section exists to stop being the only record.
///
/// `Keep` IS a decision and is why the list is not four entries. A crate examined and left alone is
/// the most common outcome and the one worth recording — without it, silence means both "nobody has
/// looked" and "looked, fine", and the lexicographer cannot tell which crates it has covered.
pub const SURFACE_DECISIONS: &[&str] = &["keep", "fold", "move", "split", "retire"];

/// Whether `d` is a decision this section can hold. The refusal names the set, on the same rule the
/// change-status validator follows: a caller that guessed should be corrected, not left to guess again.
pub fn is_valid_surface_decision(d: &str) -> bool {
    SURFACE_DECISIONS.contains(&d)
}

/// The statuses a row moves through, mirroring an issue's so a session that knows one knows the other.
pub const SURFACE_STATUSES: &[&str] = &["open", "in_progress", "done", "declined"];

/// Whether `s` is a status this section can hold.
pub fn is_valid_surface_status(s: &str) -> bool {
    SURFACE_STATUSES.contains(&s)
}

/// One roster decision about one crate.
#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct PlanSurface {
    /// The workspace member this row is about. `crate` is a Rust keyword, so the field is `krate`
    /// and serde renames it — the wire and the CLI both say `crate`, which is the word the domain
    /// uses and the one `bsc surface crates` already prints.
    #[serde(rename = "crate")]
    pub krate: String,
    /// What should happen to it. One of [`SURFACE_DECISIONS`].
    #[serde(default)]
    pub decision: String,
    /// Where the decision points, when it points somewhere — the noun a fold lands in, the noun a
    /// verb moves to. Absent for `keep`, `split` and `retire`, which name no destination.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub into: Option<String>,
    /// The nouns or verbs the decision acts on. A fold names the noun being folded; a move names the
    /// verbs moving. Empty when the decision is about the crate as a whole.
    #[serde(default)]
    pub subjects: Vec<String>,
    /// WHY. A decision with no reason is a preference, and the next session cannot tell them apart.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rationale: Option<String>,
    /// The session that should carry it out — a surface-session pane id
    /// (`surface-studio:noun-<noun>` / `surface-studio:verb-<noun>-<verb>`), or a request id for
    /// anything that touches a file. Stored as written: this crate does not resolve sessions.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub owner: Option<String>,
    #[serde(default = "open_status")]
    pub status: String,
    /// Append-only working notes, exactly as an issue's are.
    #[serde(default)]
    pub notes: Vec<String>,
    #[serde(default)]
    pub position: i64,
    #[serde(default)]
    pub updated_at: i64,
}

fn open_status() -> String {
    "open".to_string()
}

/// A crate name shaped like one: lowercase, digits and hyphens, non-empty.
///
/// # Why the check stops here, and where the real one belongs
///
/// The obvious guard is "refuse a crate the workspace does not have", and it does NOT belong in this
/// crate. `plan.db` is the per-project store for ANY project — a CRM, a mobile app, a generated
/// site — and "the workspace" is meaningless for almost all of them. Teaching `plandb` to find a
/// repository root and parse its `Cargo.toml` would make every project pay for one project's model,
/// and would be wrong the moment a plan is opened outside a Rust checkout.
///
/// The existence check belongs where the roster is known, which is `bsc surface` — it already
/// derives the workspace members from the root manifest rather than a directory listing. Recorded
/// here so the gap reads as a decision rather than an oversight.
pub fn is_crate_name_shaped(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 64
        && name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
}

impl Store {
    /// Insert or merge one roster row by crate, on the same titles-first rule `feature_upsert`
    /// follows: a supplied non-empty field overwrites, an empty or absent one keeps what is stored.
    /// So the lexicographer can lay out the crates it has examined and fill in decisions one at a
    /// time without a later write wiping an earlier one.
    ///
    /// `notes` are the exception and are APPEND-ONLY — the same rule the change record follows, for
    /// the same reason: a note reconstructed later has lost the part that mattered.
    pub fn surface_upsert(&self, row: &PlanSurface) -> Result<String, String> {
        let krate = row.krate.trim().to_string();
        if !is_crate_name_shaped(&krate) {
            return Err(format!(
                "'{krate}' is not a crate name — lowercase letters, digits and hyphens, 1..64 chars"
            ));
        }
        if !row.decision.is_empty() && !is_valid_surface_decision(&row.decision) {
            return Err(format!(
                "'{}' is not a surface decision. Valid: {}",
                row.decision,
                SURFACE_DECISIONS.join(" · ")
            ));
        }
        if !row.status.is_empty() && !is_valid_surface_status(&row.status) {
            return Err(format!(
                "'{}' is not a surface status. Valid: {}",
                row.status,
                SURFACE_STATUSES.join(" · ")
            ));
        }
        // The column DEFAULT never fires: the insert always supplies this parameter, so an unset
        // status writes '' rather than 'open'. Caught by running the verb, not by a test — the first
        // row created through the CLI listed with a blank status column and got `[]` in its detail.
        let status = if row.status.is_empty() { open_status() } else { row.status.clone() };
        let existing = self.surface_get(&krate)?;
        let merged_notes = match &existing {
            Some(prev) => {
                let mut n = prev.notes.clone();
                n.extend(row.notes.iter().cloned());
                n
            }
            None => row.notes.clone(),
        };
        let pos: i64 = self
            .conn
            .query_row("SELECT COALESCE(MAX(position), 0) + 1 FROM surfaces", [], |r| r.get(0))
            .map_err(|e| e.to_string())?;
        self.conn
            .execute(
                "INSERT INTO surfaces (krate, decision, into_noun, subjects, rationale, owner, status, notes, position, updated_at)
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, strftime('%s','now'))
                 ON CONFLICT(krate) DO UPDATE SET
                    decision   = CASE WHEN excluded.decision != ''                   THEN excluded.decision   ELSE surfaces.decision   END,
                    into_noun  = CASE WHEN COALESCE(excluded.into_noun, '') != ''     THEN excluded.into_noun  ELSE surfaces.into_noun  END,
                    subjects   = CASE WHEN excluded.subjects != '[]'                  THEN excluded.subjects   ELSE surfaces.subjects   END,
                    rationale  = CASE WHEN COALESCE(excluded.rationale, '') != ''     THEN excluded.rationale  ELSE surfaces.rationale  END,
                    owner      = CASE WHEN COALESCE(excluded.owner, '') != ''         THEN excluded.owner      ELSE surfaces.owner      END,
                    status     = CASE WHEN excluded.status != ''                      THEN excluded.status     ELSE surfaces.status     END,
                    notes      = excluded.notes,
                    updated_at = excluded.updated_at",
                params![
                    krate,
                    row.decision,
                    row.into,
                    serde_json::to_string(&row.subjects).unwrap_or_else(|_| "[]".into()),
                    row.rationale,
                    row.owner,
                    status,
                    serde_json::to_string(&merged_notes).unwrap_or_else(|_| "[]".into()),
                    pos,
                ],
            )
            .map_err(|e| e.to_string())?;
        Ok(krate)
    }

    /// One row by crate, or `None`.
    pub fn surface_get(&self, krate: &str) -> Result<Option<PlanSurface>, String> {
        let mut st = self
            .conn
            .prepare("SELECT krate, decision, into_noun, subjects, rationale, owner, status, notes, position, updated_at FROM surfaces WHERE krate = ?1")
            .map_err(|e| e.to_string())?;
        let mut rows = st.query(params![krate]).map_err(|e| e.to_string())?;
        match rows.next().map_err(|e| e.to_string())? {
            Some(r) => Ok(Some(row_to_surface(r)?)),
            None => Ok(None),
        }
    }

    /// Every row, in the order they were first recorded.
    pub fn surface_list(&self) -> Result<Vec<PlanSurface>, String> {
        let mut st = self
            .conn
            .prepare("SELECT krate, decision, into_noun, subjects, rationale, owner, status, notes, position, updated_at FROM surfaces ORDER BY position")
            .map_err(|e| e.to_string())?;
        let mut rows = st.query([]).map_err(|e| e.to_string())?;
        let mut out = Vec::new();
        while let Some(r) = rows.next().map_err(|e| e.to_string())? {
            out.push(row_to_surface(r)?);
        }
        Ok(out)
    }

    /// Move one row's status. Refuses an unknown status naming the set, rather than storing it.
    pub fn surface_status(&self, krate: &str, status: &str) -> Result<(), String> {
        if !is_valid_surface_status(status) {
            return Err(format!(
                "'{status}' is not a surface status. Valid: {}",
                SURFACE_STATUSES.join(" · ")
            ));
        }
        let n = self
            .conn
            .execute(
                "UPDATE surfaces SET status = ?2, updated_at = strftime('%s','now') WHERE krate = ?1",
                params![krate, status],
            )
            .map_err(|e| e.to_string())?;
        if n == 0 {
            return Err(format!("no surface row for '{krate}'"));
        }
        Ok(())
    }

    /// Append one note. There is deliberately no verb that removes one.
    pub fn surface_note(&self, krate: &str, note: &str) -> Result<(), String> {
        let mut row = self
            .surface_get(krate)?
            .ok_or_else(|| format!("no surface row for '{krate}'"))?;
        row.notes.push(note.to_string());
        self.conn
            .execute(
                "UPDATE surfaces SET notes = ?2, updated_at = strftime('%s','now') WHERE krate = ?1",
                params![krate, serde_json::to_string(&row.notes).unwrap_or_else(|_| "[]".into())],
            )
            .map_err(|e| e.to_string())?;
        Ok(())
    }

    /// Delete one row.
    pub fn surface_remove(&self, krate: &str) -> Result<(), String> {
        bsc_sqlite_util::delete_by(&self.conn, "surfaces", "krate", krate).map_err(|e| e.to_string())
    }
}

fn row_to_surface(r: &rusqlite::Row<'_>) -> Result<PlanSurface, String> {
    let get_s = |i: usize| -> Result<String, String> { r.get::<_, String>(i).map_err(|e| e.to_string()) };
    let get_o = |i: usize| -> Result<Option<String>, String> { r.get::<_, Option<String>>(i).map_err(|e| e.to_string()) };
    let json_vec = |s: Option<String>| -> Vec<String> {
        s.and_then(|v| serde_json::from_str(&v).ok()).unwrap_or_default()
    };
    Ok(PlanSurface {
        krate: get_s(0)?,
        decision: get_s(1)?,
        into: get_o(2)?,
        subjects: json_vec(get_o(3)?),
        rationale: get_o(4)?,
        owner: get_o(5)?,
        status: get_s(6)?,
        notes: json_vec(get_o(7)?),
        position: r.get(8).unwrap_or(0),
        updated_at: r.get(9).unwrap_or(0),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn store() -> Store {
        Store::open_in_memory().expect("in-memory plan store")
    }

    /// The merge rule features already follow, asserted here because the whole point of the section
    /// is that the lexicographer lays crates out first and decides about them one at a time. A second
    /// `add` that wiped the first would make that workflow lossy.
    #[test]
    fn a_later_add_merges_rather_than_clobbering() {
        let s = store();
        s.surface_upsert(&PlanSurface { krate: "bsc-component".into(), decision: "fold".into(), ..Default::default() })
            .expect("first add");
        s.surface_upsert(&PlanSurface { krate: "bsc-component".into(), into: Some("ui".into()), ..Default::default() })
            .expect("detail fill");
        let row = s.surface_get("bsc-component").unwrap().expect("row");
        assert_eq!(row.decision, "fold", "the earlier decision survives a write that did not restate it");
        assert_eq!(row.into.as_deref(), Some("ui"), "and the later detail landed");
    }

    /// Notes APPEND, on the same rule the change record follows: a note reconstructed later has lost
    /// the part that mattered, so nothing may drop one.
    #[test]
    fn notes_append_and_nothing_removes_one() {
        let s = store();
        s.surface_upsert(&PlanSurface { krate: "logs".into(), notes: vec!["three nouns on one crate".into()], ..Default::default() })
            .unwrap();
        s.surface_upsert(&PlanSurface { krate: "logs".into(), notes: vec!["metrics and perf are the other two".into()], ..Default::default() })
            .unwrap();
        s.surface_note("logs", "operator reported the cost").unwrap();
        let row = s.surface_get("logs").unwrap().unwrap();
        assert_eq!(row.notes.len(), 3, "every note survives: {:?}", row.notes);
        assert_eq!(row.notes[0], "three nouns on one crate", "in the order they were written");
    }

    /// `keep` is a DECISION, not the absence of one. Without it an empty row means both "nobody has
    /// looked at this crate" and "looked, it is fine", and the lexicographer cannot tell which crates
    /// it has covered — which is the whole reason the section exists rather than a list of problems.
    #[test]
    fn keep_is_a_decision_and_is_distinguishable_from_silence() {
        let s = store();
        s.surface_upsert(&PlanSurface { krate: "bsc-util".into(), decision: "keep".into(),
            rationale: Some("no verbs, but its change rebuilds 36 of 40 crates".into()), ..Default::default() }).unwrap();
        s.surface_upsert(&PlanSurface { krate: "bsc-tunnel".into(), ..Default::default() }).unwrap();
        let examined = s.surface_get("bsc-util").unwrap().unwrap();
        let unexamined = s.surface_get("bsc-tunnel").unwrap().unwrap();
        assert_eq!(examined.decision, "keep");
        assert!(examined.rationale.is_some(), "a keep carries its reason or it is indistinguishable from a shrug");
        assert!(unexamined.decision.is_empty(), "an unexamined crate reads as undecided, not as keep");
    }

    /// The closed sets are enforced at the boundary and the refusal NAMES the set — a caller that
    /// guessed should be corrected, not left to guess again.
    #[test]
    fn an_unknown_decision_or_status_is_refused_naming_the_valid_set() {
        let s = store();
        let e = s.surface_upsert(&PlanSurface { krate: "bsc-ui".into(), decision: "merge".into(), ..Default::default() })
            .expect_err("'merge' is not one of the five");
        assert!(e.contains("fold"), "the refusal lists what is valid: {e}");
        let e2 = s.surface_upsert(&PlanSurface { krate: "bsc-ui".into(), status: "closed".into(), ..Default::default() })
            .expect_err("'closed' is not a surface status");
        assert!(e2.contains("declined"), "the refusal lists what is valid: {e2}");
        assert!(s.surface_get("bsc-ui").unwrap().is_none(), "a refused write stores nothing");
    }

    /// The shape guard, and the ONE thing this crate can check about a crate name.
    ///
    /// It deliberately stops short of "does the workspace have it". `plan.db` is the per-project store
    /// for ANY project, so "the workspace" is meaningless for almost all of them; teaching plandb to
    /// find a repo root and parse a Cargo.toml would make every project pay for one project's model.
    /// The existence check belongs to `bsc surface`, which already derives the members from the root
    /// manifest. Asserted here so the boundary is a decision in the test suite rather than an omission.
    #[test]
    fn a_crate_name_is_shape_checked_here_and_existence_checked_elsewhere() {
        for good in ["bsc-util", "plandb", "bsc-graph-store", "atlasdb"] {
            assert!(is_crate_name_shaped(good), "{good} is a crate name");
        }
        for bad in ["", "Bsc-Util", "bsc util", "../etc", "bsc_util"] {
            assert!(!is_crate_name_shaped(bad), "{bad:?} is not");
        }
        let s = store();
        let e = s.surface_upsert(&PlanSurface { krate: "../etc".into(), ..Default::default() }).expect_err("refused");
        assert!(e.contains("not a crate name"), "{e}");
        // ...and a crate that does not exist IS accepted, which is the boundary being asserted.
        assert!(s.surface_upsert(&PlanSurface { krate: "bsc-nonexistent".into(), ..Default::default() }).is_ok());
    }

    /// A NEW row is `open`, not blank. The column DEFAULT cannot do this — the insert always supplies
    /// the parameter, so an unset status wrote the empty string and the listing showed a blank column.
    /// Found by running `bsc plan surface add` and reading the output, which no test above did.
    #[test]
    fn a_new_row_defaults_to_open() {
        let s = store();
        s.surface_upsert(&PlanSurface { krate: "bsc-cad".into(), decision: "keep".into(), ..Default::default() }).unwrap();
        assert_eq!(s.surface_get("bsc-cad").unwrap().unwrap().status, "open");
        // ...and an explicit status still wins.
        s.surface_upsert(&PlanSurface { krate: "bsc-cad".into(), status: "done".into(), ..Default::default() }).unwrap();
        assert_eq!(s.surface_get("bsc-cad").unwrap().unwrap().status, "done");
    }

    /// A status move must find its row. Silently creating one would let a typo mint a roster entry
    /// for a crate nobody decided anything about.
    #[test]
    fn a_status_move_on_an_unknown_crate_is_refused_rather_than_creating_one() {
        let s = store();
        let e = s.surface_status("bsc-nope", "done").expect_err("no such row");
        assert!(e.contains("bsc-nope"), "{e}");
        assert!(s.surface_list().unwrap().is_empty(), "and nothing was created");
    }
}
